const icons={leaf:'<path d="M12 21v-9m0 5C4 18 3 12 3 8c6 0 9 2 9 9Zm0-5c0-6 4-9 10-9 0 7-3 11-10 9Z"/>',dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v2"/>',settings:'<path d="m12 3 2 3 4-1 1 4 3 3-3 3-1 4-4-1-2 3-2-3-4 1-1-4-3-3 3-3 1-4 4 1Z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',shield:'<path d="M12 3 3 7v5c0 5 9 10 9 10s9-5 9-10V7Z"/><path d="m8 12 3 3 5-6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',alert:'<path d="m12 3 10 18H2Z"/><path d="M12 9v5m0 3v1"/>',play:'<path d="m7 3 15 9-15 9Z"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6Zm-2 2 5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>'};
const ic=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.leaf}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], uid=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,"0")).join("");
let state,revision=0,busy=false,search='',filter='all',scheduleDate='',scheduleView=window.matchMedia('(max-width: 767px)').matches?'day':'week',historyDate='',lastFocus;
let scheduleSearch='',scheduleCrew='',scheduleUndo=null,saveMessage='All changes saved';
const modal=$('#modal');
const dateKey=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:state?.settings.timezone||'Australia/Melbourne',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const today=()=>dateKey();
const dateLabel=(s,opts={weekday:'short',day:'numeric',month:'short'})=>new Date(s+'T12:00:00').toLocaleDateString('en-AU',opts);
const shiftDate=(s,n)=>{let d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const nextVisit=s=>dueDate(s);
const siteStatus=s=>nextVisit(s)&&nextVisit(s)<today()?'overdue':'active';
const site=id=>state.sites.find(s=>s.id===id), member=id=>state.members.find(m=>m.id===id), crew=id=>state.crews.find(c=>c.id===id);
const assignee=j=>assignmentLabel(state,j);
const activeEntry=()=>state.entries.find(e=>!e.end);
const timeLabel=s=>new Date(s).toLocaleTimeString('en-AU',{timeZone:state.settings.timezone,hour:'numeric',minute:'2-digit'});
const duration=(start,end)=>{let m=Math.max(0,Math.floor(((end?new Date(end):new Date())-new Date(start))/60000));return `${Math.floor(m/60)}h ${m%60}m`};
const btn=(label,action,icon='plus',classes='primary',attrs='')=>`<button class="btn ${classes}" data-action="${action}" ${attrs}>${ic(icon)}<span>${label}</span></button>`;
const link=(label,path,icon,classes='secondary')=>`<a class="btn ${classes}" href="${path}">${ic(icon)}<span>${label}</span></a>`;
const input=(label,name,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const textarea=(label,name,value='',attrs='')=>`<label class="field">${label}<textarea name="${name}" ${attrs}>${esc(value)}</textarea></label>`;
const select=(label,name,options,value='',attrs='')=>`<label class="field">${label}<select name="${name}" ${attrs}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const empty=(title,desc,action='',icon='leaf')=>`<div class="empty"><div class="empty-icon">${ic(icon)}</div><h3>${title}</h3><p>${desc}</p>${action}</div>`;
const pill=(text,type='')=>`<span class="pill ${type}">${esc(text)}</span>`;
function toast(msg,error=false){$('#toast').textContent=msg;$('#toast').className=error?'visible error':'visible';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').className='',5000)}
async function responseBody(r){if(r.status===401){showLogin();throw new Error('Please sign in to continue.');}if(!r.headers.get('content-type')?.includes('application/json'))throw new Error('The server returned an unexpected response. Reload and try again.');return r.json();}
async function load(){const r=await fetch('/api/state',{cache:'no-store'});const b=await responseBody(r);if(!r.ok)throw new Error(b.error||'Unable to load records.');state=b.data;revision=b.revision;scheduleUndo=null;}
async function save(change,message='Saved'){
 if(busy)return false;busy=true;const next=structuredClone(state);document.body.classList.add('saving');setSaveStatus('Saving…');
 try{preserveTeamHistory(next);change(next);const payload=JSON.stringify({data:next,revision});if(new TextEncoder().encode(payload).length>4*1024*1024)throw new Error('Workspace exceeds 4 MiB. Export a backup and reduce photos.');const r=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:payload});const b=await responseBody(r);if(!r.ok){if(r.status===409){await load();render()}throw new Error(b.error||'Unable to save records.')}state=next;revision=b.revision;scheduleUndo=null;saveMessage='All changes saved';render();if(message)toast(message);return true}catch(e){setSaveStatus('Could not save — '+e.message);toast(e.message,true);return false}finally{busy=false;document.body.classList.remove('saving')}
}
const navs=[['Dashboard','/','dashboard'],['Sites','/sites','pin'],['Schedule','/schedule','calendar'],['History','/history','clock'],['Time Tracking','/time-tracking','clock'],['Crews & Members','/crews','team'],['Settings','/settings','settings']];
function navigate(path){history.pushState({},'',path);search='';filter='all';render();window.scrollTo(0,0)}
function render(){
 if(!state)return;
 const path=location.pathname,current=path==='/teams'?'/crews':path;
 const navHtml=navs.map(([n,p,i])=>`<a href="${p}" class="nav-item ${p==='/'?current==='/'?'active':'':current.startsWith(p)?'active':''}" ${current===p?'aria-current="page"':''}>${ic(i)}<span>${n}</span></a>`).join('');
 const names=(state.settings.name||'Owner').split(' ').map(x=>x[0]).join('').slice(0,2);
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="/"><img src="/icon.svg" alt="" width="40" height="40"><span>GardenPro</span></a><div class="sidebar-action">${link('Add New Site','/sites/new','plus','primary')}</div><nav aria-label="Main navigation">${navHtml}</nav><div class="sidebar-foot"><div class="private">${ic('shield')} Private workspace</div><button class="btn secondary" data-action="logout">Sign out</button><div class="profile"><div class="avatar">${esc(names)}</div><div><b>${esc(state.settings.name||'Your workspace')}</b><small>${esc(state.settings.company||'Garden maintenance')}</small></div></div></div></aside><main id="main" tabindex="-1"><button class="btn secondary mobile-logout" data-action="logout">Sign out</button>${content(current)}</main><nav class="bottom-nav" aria-label="Mobile navigation">${navs.filter(x=>['/','/sites','/schedule','/history','/settings'].includes(x[1])).map(([n,p,i])=>`<a href="${p}" ${current===p?'aria-current="page"':''} class="${current===p||p!=='/'&&current.startsWith(p)?'active':''}">${ic(i)}<span>${n}</span></a>`).join('')}<button data-action="more">${ic('more')}<span>More</span></button></nav>`;
 document.title=(current==='/'?'Dashboard':navs.find(x=>x[1]===current)?.[0]||'Site details')+' · Gardener Pro';
 if($('#search')){$('#search').value=search;$('#search').addEventListener('input',e=>{search=e.target.value;renderListOnly()})}
 updateTimers();
}
function header(title,subtitle,actions='',back=false){return `<header class="page-header"><div class="heading">${back?'<a class="icon-button" aria-label="Back to sites" href="/sites">'+ic('back')+'</a>':'<img class="mobile-brand" src="/icon.svg" alt="" width="32" height="32">'}<div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div></div><div class="header-actions">${actions}</div></header>`}
function content(path){
 if(path==='/')return dashboard();
 if(path==='/sites')return sitesPage();
 if(path==='/sites/new')return siteForm();
 let match=path.match(/^\/sites\/([^/]+)(\/edit)?$/);if(match){const s=site(match[1]);return s?match[2]?siteForm(s):siteDetail(s):notFound()}
 if(path==='/schedule')return schedule();
 if(path==='/history')return historyPage();
 if(path==='/time-tracking')return tracking();
 if(path==='/crews')return crewsPage();
 if(path==='/settings')return settingsPage();
 return notFound();
}
function dashboard(){
 const jobs=state.jobs.filter(j=>j.status!=='deferred'&&j.date===today()),done=jobs.filter(j=>j.status==='completed').length,overdue=state.sites.filter(s=>siteStatus(s)==='overdue').length;
 const hour=Number(new Intl.DateTimeFormat('en-AU',{timeZone:state.settings.timezone,hour:'numeric',hourCycle:'h23'}).format(new Date()));
 const greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';
 const stats=[['My Jobs Today',jobs.length,'calendar','green'],['Completed',done,'check','green'],['Total Sites',state.sites.length,'pin',''],['Overdue',overdue,'alert','amber']];
 return header(`${greeting}, ${(state.settings.name||'there').split(' ')[0]}!`,jobs.length-done?`${jobs.length-done} jobs remaining today`:'No jobs remaining today',`<span class="date-badge">${dateLabel(today(),{weekday:'long',day:'numeric',month:'long'})}</span>`)+`<div class="page"><section class="stats">${stats.map(([l,v,i,c])=>`<div class="stat ${c}"><div class="stat-icon">${ic(i)}</div><strong>${v}</strong><span>${l}</span></div>`).join('')}</section><section><div class="section-heading"><h2 class="eyebrow">Quick actions</h2><span class="muted tiny">A little planning. A lot of growing.</span></div><div class="quick-actions">${link('Add Site','/sites/new','plus','quick green')}${link('Schedule','/schedule','calendar','quick')}${link('History','/history','clock','quick')}</div></section><section>${activeEntry()?timerCard():''}${state.jobs.some(j=>j.status==='deferred')?`<a class="notice amber" href="/schedule"><b>${state.jobs.filter(j=>j.status==='deferred').length} jobs waiting to reschedule</b></a>`:''}${overdue?`<a class="notice amber" href="/sites?status=overdue">${ic('alert')}<span><b>${overdue} ${overdue===1?'site needs':'sites need'} attention</b><small>Review overdue visits and plan the next job.</small></span>${ic('arrow')}</a>`:''}<div class="section-heading"><h2>Today's jobs</h2><a class="text-link" href="/schedule">View schedule ${ic('arrow')}</a></div>${jobs.length?`<div class="job-list">${jobs.map(jobCard).join('')}</div>`:empty('No jobs scheduled',state.sites.length?"You’re all caught up for today.":'Start by adding your first site, then schedule a visit.',state.sites.length?link('View Schedule','/schedule','calendar'):link('Add your first site','/sites/new','plus','primary'))}${!state.sites.length?`<div class="note">${ic('shield')}<p>Your new workspace is ready for real records. Existing Lovable records have not been imported.</p></div>`:''}</section></div>`;
}
function timerCard(){let e=activeEntry();return `<div class="timer-card"><span class="live-dot"></span><div><b>${esc(siteTitle(site(e.siteId)))} · Clocked in</b><small>Started ${timeLabel(e.start)} · <span data-timer="${e.id}">${duration(e.start,null)}</span></small></div>${btn('Clock Out','clockout','stop','secondary')}</div>`}
function jobCard(j){const s=site(j.siteId);return `<article class="job-card"><button class="job-open" data-action="job" data-id="${j.id}"><div class="job-icon ${j.status==='completed'?'done':''}">${ic(j.status==='completed'?'check':'leaf')}</div><div><h3>${esc(siteTitle(s))}</h3>${s?.name?.trim()?`<p>${ic('pin')}${esc(s.address)}</p>`:''}${j.status!=='completed'?visitNote(s):''}${deferralNote(j)}<div class="job-meta"><span>${j.time?esc(j.time):'Flexible time'}</span><span>${esc(s?.estimatedTime||'2h')}</span><span>${esc(assignee(j))}</span></div></div></button><div class="job-tail">${pill(j.status==='in-progress'?'In progress':j.status==='completed'?'Completed':j.status==='deferred'?'Waiting':'Scheduled',j.status==='completed'?'green':j.status==='in-progress'?'amber':'')}${j.status==='deferred'?btn('Reschedule','move-job','calendar','secondary',`data-id="${j.id}"`):''}${j.status==='scheduled'?btn('Start Job','startjob','play','outline',`data-id="${j.id}"`):j.status==='in-progress'?btn('Complete','complete','check','primary',`data-id="${j.id}"`):''}</div></article>`}
function sitesPage(){return header('Sites',`${state.sites.length} garden ${state.sites.length===1?'site':'sites'} to manage`,btn('Review addresses','review-addresses','pin','secondary')+btn('Export','export-sites','download','secondary')+link('Add Site','/sites/new','plus','primary'))+`<div class="page"><section><div class="toolbar"><label class="search">${ic('search')}<input id="search" aria-label="Search sites" placeholder="Search sites by name or address…"></label><select id="site-filter" aria-label="Filter sites"><option value="all">All sites</option><option value="active">Active</option><option value="overdue">Overdue</option></select></div><div id="site-list">${siteList()}</div></section></div>`}
function siteList(){let chosen=new URLSearchParams(location.search).get('status')||filter;const list=state.sites.filter(s=>((s.name||'')+' '+s.address).toLowerCase().includes(search.toLowerCase())&&(chosen==='all'||siteStatus(s)===chosen));return list.length?`<div class="site-grid">${list.map(s=>`<a class="site-card" href="/sites/${s.id}"><div class="site-card-top"><div class="site-icon">${ic('leaf')}</div>${pill(siteStatus(s)==='overdue'?'Overdue':'Active',siteStatus(s)==='overdue'?'amber':'green')}</div><h2>${esc(siteTitle(s))}</h2>${s.name?.trim()?`<p class="address">${ic('pin')}${esc(s.address)}</p>`:''}<div class="site-meta"><span>${ic('calendar')}${esc(s.frequency)}</span><span>${ic('clock')}${esc(s.estimatedTime)}</span></div><div class="site-card-footer"><span>${nextVisit(s)?'Next due '+dateLabel(nextVisit(s)):s.lastCompleted?'Completed '+dateLabel(s.lastCompleted):'No visits completed yet'}</span>${ic('arrow')}</div></a>`).join('')}</div>`:empty('No sites found',search||chosen!=='all'?'Try another search or filter.':'Add a site to keep its details, tasks and visits in one place.',link('Add Site','/sites/new','plus','primary'),'pin')}
function renderListOnly(){if($('#site-list'))$('#site-list').innerHTML=siteList()}
const visitNote=s=>s?.nextVisitNote?`<span class="next-visit-note"><strong>Reminder</strong><span>${esc(s.nextVisitNote)}</span></span>`:'';
function assignmentControl(record={},label='Assigned to',disabled=false){const selected=assignmentValue(record);return select(label,'assignment',[['','Unassigned'],...state.members.filter(m=>!m.archived||selected==='member:'+m.id).map(m=>['member:'+m.id,m.name+(m.archived?' (archived)':'')]),...state.crews.filter(c=>!c.archived||selected==='crew:'+c.id).map(c=>['crew:'+c.id,c.name+' · Crew'+(c.archived?' (archived)':'')])],selected,disabled?'disabled':'');}
function attendanceControl(j){const ids=assignedMemberIds(state,j);return `<fieldset class="attendance"><legend>Who attended?</legend><p class="tiny muted">Confirm the people who actually worked on this visit. Leave all unchecked if unknown.</p>${state.members.filter(m=>!m.archived||ids.includes(m.id)).map(m=>`<label class="check-field"><input type="checkbox" name="attendee" value="${m.id}" ${ids.includes(m.id)?'checked':''}>${esc(m.name)}${m.archived?' (archived)':''}</label>`).join('')||'<p class="muted">Add named members in Crews & Members to record attendance.</p>'}</fieldset>`;}
function attendanceSummary(j){if(j.status!=='completed')return '';const snap=j.teamSnapshot;return `<p class="muted">${snap?.source==='confirmed'?'Attended: '+esc(snap.members.map(m=>m.name).join(', ')||'Not recorded'):'Attendance not recorded for this older visit; assignment is retained for reference.'}</p>`;}
function addressFields(s={}){const p=addressDraft(s);return `<div class="address-editor">${s.address?`<p class="tiny muted">Current address: <b>${esc(s.address)}</b></p>`:''}<p class="tiny muted">Suggestions need your review. Suburbs and postcodes have not been checked against a map or postal service.</p><div class="form-grid">${input('Unit number (optional)','addressUnit',p.unit,'text','maxlength="50"')}${input('Street number and name *','addressStreet',p.street,'text','required maxlength="250"')}${input('Suburb','addressSuburb',p.suburb,'text','maxlength="100"')}${select('State','addressState',ADDRESS_STATES.map(x=>[x,x]),p.state)}${input('Postcode','addressPostcode',p.postcode,'text','inputmode="numeric" pattern="[0-9]{4}" maxlength="4"')}</div><label class="check-field"><input type="checkbox" name="addressConfirmed" ${p.confirmed?'checked':''}>I have checked the unit, street, suburb, state and postcode.</label><p class="tiny muted">Confirmed fields become the full address. For existing sites, unconfirmed drafts keep the current address unchanged.</p></div>`;}
function addressFromForm(values,fd,s){return addressUpdate(s,{unit:values.addressUnit,street:values.addressStreet,suburb:values.addressSuburb,state:values.addressState,postcode:values.addressPostcode,confirmed:fd.has('addressConfirmed')});}
function reviewAddresses(){const pending=state.sites.filter(s=>!s.addressParts?.confirmed),ready=state.sites.length-pending.length;openModal('Review site addresses',`<p class="muted">${ready} confirmed · ${pending.length} need review. Check each address before suburb grouping is enabled.</p>${pending.map(s=>`<button class="address-review-row" data-action="review-address" data-id="${s.id}"><b>${esc(siteTitle(s))}</b><span>${esc(s.address)}</span><small>${!addressDraft(s).suburb?'Suburb needs checking · ':''}${!addressDraft(s).postcode?'Postcode missing':'Confirm details'}</small></button>`).join('')||'<p class="muted">All site addresses have been confirmed. Edit a site whenever a correction is needed.</p>'}`,true);}
function reviewAddress(id){const s=site(id);if(!s)return;openModal('Correct address',`<form id="address-form" data-id="${id}"><p><b>${esc(siteTitle(s))}</b></p>${addressFields(s)}${formEnd('Save & return to review')}</form>`);}
function siteForm(s={}){return header(s.id?'Edit Site':'Add New Site',s.id?'Update site details':'Enter site details','',true)+`<div class="page narrow"><form id="site-form" data-id="${s.id||''}"><section class="panel"><h2>${ic('pin')}Basic information</h2><p class="muted">For houses and units, leave the name blank. The address becomes the title.</p><div class="form-grid">${input('Site name (optional)','name',s.name,'text','maxlength="200" placeholder="Commercial site or business name"')}${select('Visit Frequency *','frequency',[['weekly','Weekly'],['fortnightly','Fortnightly'],['monthly','Monthly'],['one-off','One-off']],s.frequency||'weekly')}${select('Estimated Time','estimatedTime',[['30m','30 minutes'],['1h','1 hour'],['2h','2 hours'],['3h','3 hours'],['4h','4 hours']],s.estimatedTime||'2h')}${select('Preferred Day','preferredDay',[['','Any day'],...[['1','Monday'],['2','Tuesday'],['3','Wednesday'],['4','Thursday'],['5','Friday'],['6','Saturday'],['0','Sunday']]],s.preferredDay||'')}${assignmentControl(s,'Default assignment')}</div>${addressFields(s)}<label class="check-field"><input name="rideOn" type="checkbox" ${s.rideOn?'checked':''}><span><b>Ride-on Required</b><small>This site requires ride-on mower equipment.</small></span></label></section><section class="panel"><h2>Additional details</h2>${textarea('Parking Instructions','parking',s.parking,'maxlength="2000" placeholder="Where to park, access or gate details"')}${textarea('Reminder','nextVisitNote',s.nextVisitNote,'maxlength="2000" placeholder="e.g. Trim back bushes next time"')}<p class="tiny muted">Highlighted on upcoming jobs. Keep it until done; clear it when no longer needed.</p>${textarea('Notes','notes',s.notes,'maxlength="5000" placeholder="Anything useful to know before a visit"')}</section><div class="form-actions"><a class="btn secondary" href="${s.id?'/sites/'+s.id:'/sites'}">Cancel</a><button class="btn primary" type="submit">${ic('check')}${s.id?'Save Changes':'Create Site'}</button></div></form></div>`}
function siteDetail(s){const visits=state.jobs.filter(j=>j.siteId===s.id).sort((a,b)=>b.date.localeCompare(a.date));return header(siteTitle(s),s.name?.trim()?s.address:'Site details',btn('Edit','edit-site','edit','secondary',`data-id="${s.id}"`)+btn('Schedule','schedule-site','calendar','primary',`data-id="${s.id}"`),true)+`<div class="page">${visitNote(s)}<section class="detail-grid"><div class="panel"><div class="section-heading"><h2>Site details</h2>${pill(siteStatus(s)==='overdue'?'Overdue':'Active',siteStatus(s)==='overdue'?'amber':'green')}</div><dl class="details"><div><dt>Visit frequency</dt><dd>${esc(s.frequency)}</dd></div><div><dt>Estimated time</dt><dd>${esc(s.estimatedTime)}</dd></div><div><dt>Preferred day</dt><dd>${s.preferredDay!==''&&s.preferredDay!=null?['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][s.preferredDay]:'Any day'}</dd></div><div><dt>Assigned to</dt><dd>${esc(assignee(s))}</dd></div><div><dt>Ride-on mower</dt><dd>${s.rideOn?'Required':'Not required'}</dd></div><div><dt>Last completed</dt><dd>${s.lastCompleted?dateLabel(s.lastCompleted):'No visits yet'}</dd></div></dl><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.address)}" target="_blank" rel="noopener noreferrer">Open address in maps ${ic('arrow')}</a></div><div class="panel"><h2>Notes & access</h2><h3 class="small-heading">Parking instructions</h3><p class="preserve muted">${esc(s.parking||'No parking instructions added.')}</p><h3 class="small-heading">Notes</h3><p class="preserve muted">${esc(s.notes||'No notes added.')}</p></div></section><section class="panel"><div class="section-heading"><h2>Site tasks <span class="count">${s.tasks.length}</span></h2>${btn('Add Task','addtask','plus','secondary',`data-id="${s.id}"`)}</div>${s.tasks.length?`<div class="tasks">${s.tasks.map(t=>`<div class="task"><label><input type="checkbox" data-task="${t.id}" data-site="${s.id}" ${t.done?'checked':''}><span class="${t.done?'struck':''}">${esc(t.name)}</span></label><button class="icon-button" aria-label="Delete task ${esc(t.name)}" data-action="delete-task" data-id="${t.id}" data-site="${s.id}">${ic('trash')}</button></div>`).join('')}</div>`:'<p class="muted">Add a checklist for regular work at this site.</p>'}</section><section><div class="section-heading"><h2>Visits</h2>${btn('Delete site','delete-site','trash','text-danger',`data-id="${s.id}"`)}</div>${visits.length?`<div class="job-list">${visits.map(j=>`<div class="visit-label">${dateLabel(j.date)}</div>${jobCard(j)}`).join('')}</div>`:empty('No visits yet','Schedule the first visit for this site.',btn('Schedule a Job','schedule-site','calendar','primary',`data-id="${s.id}"`),'calendar')}</section></div>`}
function scheduleMatches(j){const s=site(j.siteId);return matchesAssignment(state,j,scheduleCrew)&&((s?.name||'')+' '+(s?.address||'')).toLowerCase().includes(scheduleSearch.toLowerCase());}
function scheduleCard(j){const s=site(j.siteId),open=j.status!=='completed',attrs=`data-id="${j.id}"`,meta=[j.time,s?.estimatedTime,...(!scheduleCrew?[assignee(j)]:[])].filter(Boolean),last=j.deferrals?.at(-1);return `<article class="schedule-item plan-card ${j.status}" data-job-id="${j.id}"><div class="plan-heading"><button class="plan-title" data-action="job" ${attrs}><strong>${esc(siteTitle(s))}</strong></button>${open?`<button class="drag-handle" data-action="move-job" ${attrs} aria-label="Move or reorder ${esc(siteTitle(s))}" title="Drag or tap to move">↕</button>`:''}</div><div class="plan-meta">${esc(meta.join(' · '))}</div>${j.status==='in-progress'?'<span class="compact-status">In progress</span>':''}${open&&s?.nextVisitNote?`<button class="compact-note" data-action="job" ${attrs} aria-label="Read full reminder for ${esc(siteTitle(s))}"><strong>Reminder</strong><span>${esc(s.nextVisitNote)}</span></button>`:''}${j.status==='deferred'&&last?`<button class="compact-note" data-action="job" ${attrs}><strong>Waiting · ${dateLabel(last.date)}</strong><span>${esc(last.reason)}</span></button>`:''}${open?`<div class="plan-actions">${j.status==='scheduled'?btn('Start','startjob','play','primary',attrs):j.status==='in-progress'?btn('Complete','complete','check','primary',attrs):btn('Do today','do-today','calendar','primary',attrs)}<button class="btn secondary plan-more" data-action="job-actions" ${attrs} aria-label="More actions for ${esc(siteTitle(s))}">${ic('more')}</button></div>`:''}</article>`;}
function workloadLabel(jobs){const w=dayWorkload(jobs,state.sites);return `${w.count} ${w.count===1?'job':'jobs'} · ${Math.floor(w.minutes/60)?Math.floor(w.minutes/60)+'h':''}${w.minutes%60?(Math.floor(w.minutes/60)?' ':'')+w.minutes%60+'m':w.minutes?'':'0h'}`;}
function completedGroup(jobs){return jobs.length?`<details class="completed-group"><summary>✓ ${jobs.length} completed</summary>${jobs.map(j=>`<button class="completed-row" data-action="job" data-id="${j.id}">${esc(siteTitle(site(j.siteId)))}</button>`).join('')}</details>`:'';}
function jobActions(id){const j=state.jobs.find(j=>j.id===id);if(!j)return;const attrs=`data-id="${j.id}"`;openModal('Job actions',`<p class="muted">${esc(siteTitle(site(j.siteId)))}</p><div class="compact-menu">${['scheduled','in-progress'].includes(j.status)?btn('Complete','complete','check','secondary',attrs)+btn('Defer','defer-job','clock','secondary',attrs):''}${j.status!=='completed'?btn('Reschedule','move-job','calendar','secondary',attrs):''}${j.status!=='completed'?btn('Reassign','reassign','team','secondary',attrs):''}${btn('View details','job','arrow','secondary',attrs)}</div>`);}
function schedule(){
 if(!scheduleDate)scheduleDate=today();
 const monday=shiftDate(scheduleDate,-((new Date(scheduleDate+'T12:00:00').getDay()+6)%7));
 const days=scheduleView==='day'?[scheduleDate]:Array.from({length:7},(_,i)=>shiftDate(monday,i));
 const jobs=state.jobs.filter(j=>j.status!=='deferred'&&days.includes(j.date)&&scheduleMatches(j)).sort(compareJobs);
 const waiting=state.jobs.filter(j=>j.status==='deferred').length;
 return header('Schedule','Plan the day. Keep unfinished work in sight.',btn('Add Job','addjob','plus','primary'))+`<div class="page schedule-page"><div class="planner-tools"><div class="segmented planner-tabs"><button data-action="view-today" class="${scheduleView==='day'?'selected':''}" aria-pressed="${scheduleView==='day'}">${scheduleView==='day'&&scheduleDate!==today()?'Day':'Today'}</button><button data-action="view-week" class="${scheduleView==='week'?'selected':''}" aria-pressed="${scheduleView==='week'}">Week</button><button data-action="view-waiting" class="${scheduleView==='waiting'?'selected':''}" aria-pressed="${scheduleView==='waiting'}">Waiting (${waiting})</button></div><div class="planner-save"><span id="save-state" role="status">${esc(saveMessage)}</span>${scheduleUndo?btn('Undo move','undo-schedule','back','secondary'):''}</div><div class="planner-filters"><label class="field">Find a site<input type="search" id="schedule-search" placeholder="Name or address" value="${esc(scheduleSearch)}"></label>${select('Person / crew','scheduleCrew',[['','Everyone'],['unassigned:','Unassigned'],...state.crews.map(c=>[c.id,c.name+(c.archived?' (archived)':'')]),...state.members.map(m=>['member:'+m.id,m.name+(m.archived?' (archived)':'')])],scheduleCrew,'id="schedule-crew"')}</div>${scheduleView!=='waiting'?`<div class="date-controls planner-dates"><button class="icon-button" aria-label="Previous ${scheduleView}" data-action="prev-date">${ic('back')}</button><input type="date" aria-label="Schedule date" id="schedule-date" value="${scheduleDate}"><button class="icon-button" aria-label="Next ${scheduleView}" data-action="next-date">${ic('arrow')}</button><button class="btn secondary" data-action="today">Today</button>${btn('Plan this week','autoschedule','calendar','secondary')}</div>`:''}</div>${scheduleView==='waiting'?deferredQueue():`<section><p class="muted tiny schedule-help">Drag ↕ to change visit order or day. Appointment times stay fixed. Tap ↕ for move options.${scheduleSearch||scheduleCrew?' Totals below reflect the filtered jobs.':''}</p>${appointmentOrderConflict(jobs)?'<p class="notice amber">Visit order conflicts with appointment times for a crew or member. Review the order or edit the times.</p>':''}<div class="week-grid planner-grid ${scheduleView==='day'?'single':''}">${days.map(day=>{const list=jobs.filter(j=>j.date===day);return `<section class="day-column ${day===today()?'is-today':''}"><button class="day-heading" data-action="choose-day" data-date="${day}"><strong>${dateLabel(day)}</strong>${day===today()?'<small>Today</small>':''}</button><p class="day-total">${workloadLabel(list)}</p><div class="day-jobs" data-drop-date="${day}">${list.filter(j=>j.status!=='completed').map(scheduleCard).join('')}${!list.length?'<p class="day-empty">No jobs</p>':''}<button class="add-day" data-action="addjob-date" data-date="${day}" aria-label="Add job on ${dateLabel(day)}">${ic('plus')} Add job</button>${completedGroup(list.filter(j=>j.status==='completed'))}</div></section>`}).join('')}</div></section>${deferredQueue()}`}</div>`;
}

function historyPage(){let jobs=state.jobs.filter(j=>j.status==='completed'&&(!historyDate||j.date===historyDate)).sort((a,b)=>(b.completedAt||b.date).localeCompare(a.completedAt||a.date));return header('History','Completed visits and job notes',btn('Export','export-history','download','secondary'))+`<div class="page"><section><div class="toolbar"><h2>Completed visits <span class="count">${jobs.length}</span><div class="date-controls"><input aria-label="Filter history by date" type="date" id="history-date" value="${historyDate}">${historyDate?btn('All time','clear-history','close','secondary'):''}</div></div>${jobs.length?`<div class="job-list">${jobs.map(j=>`<div class="visit-label">${dateLabel(j.date)}</div>${jobCard(j)}`).join('')}</div>`:empty('No completed visits','Completed jobs and their notes will appear here.',link('View Schedule','/schedule','calendar'),'check')}</section></div>`}
function tracking(){const entries=[...state.entries].sort((a,b)=>b.start.localeCompare(a.start));const total=entries.filter(e=>dateKey(new Date(e.start))===today()).reduce((n,e)=>n+(new Date(e.end||Date.now())-new Date(e.start))/60000,0);return header('Time Tracking','Clock in, track hours and review entries',btn('Export','export-time','download','secondary')+btn('Add Entry','addentry','plus','primary'))+`<div class="page"><section>${activeEntry()?timerCard():`<div class="panel clock-panel"><div class="stat-icon green">${ic('clock')}</div><div><h2>Ready to get to work?</h2><p class="muted">Choose a site and start tracking your time.</p></div>${btn('Clock In','clockin','play','primary')}</div>`}<div class="section-heading"><h2>Time entries</h2><span class="muted">Today: ${Math.floor(total/60)}h ${Math.floor(total%60)}m</span></div>${entries.length?`<div class="panel table-wrap"><table><thead><tr><th>Site</th><th>Date</th><th>Clock in</th><th>Clock out</th><th>Duration</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${entries.map(e=>`<tr><td><b>${esc(siteTitle(site(e.siteId)))}</b><small>${esc(e.notes)}</small></td><td>${dateLabel(dateKey(new Date(e.start)))}</td><td>${timeLabel(e.start)}</td><td>${e.end?timeLabel(e.end):pill('Active','green')}</td><td ${!e.end?'data-timer="'+e.id+'"':''}>${duration(e.start,e.end)}</td><td><button class="icon-button" aria-label="Edit time entry" data-action="editentry" data-id="${e.id}">${ic('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No time entries yet','Clock in at a site or add a past entry.','','clock')}</section></div>`}
function teamCard(r,type){const filter=type==='member'?'member:'+r.id:r.id,jobs=state.jobs.filter(j=>j.date===today()&&j.status!=='deferred'&&matchesAssignment(state,j,filter)),done=jobs.filter(j=>j.status==='completed').length,pending=state.jobs.filter(j=>j.status!=='completed'&&matchesAssignment(state,j,filter)).length;return `<article class="panel team-card"><div class="section-heading"><h3>${esc(r.name)}</h3>${r.archived?pill('Archived'):''}</div><p class="muted">${type==='crew'?(r.memberIds.map(id=>{const m=member(id);return m?esc(m.name)+(m.archived?' (archived)':''):''}).filter(Boolean).join(', ')||'No members'):esc(r.role||'Team member')}</p><p class="team-workload">${workloadLabel(jobs)} · ${done} completed today</p>${r.archived&&pending?`<p class="notice amber">${pending} open jobs still assigned. Review these in Schedule, including Waiting.</p>`:''}<div class="button-row">${btn('View schedule','team-schedule','calendar','secondary',`data-assignment="${esc(filter)}"`)}${btn('Edit',type==='member'?'editmember':'editcrew','edit','secondary',`data-id="${r.id}"`)}</div></article>`;}
function crewsPage(){const activeMembers=state.members.filter(m=>!m.archived),activeCrews=state.crews.filter(c=>!c.archived),archived=[...state.members.filter(m=>m.archived).map(m=>teamCard(m,'member')),...state.crews.filter(c=>c.archived).map(c=>teamCard(c,'crew'))];return header('Crews & Members','Today’s assignments and team workload',btn('Add Member','addmember','plus','primary'))+`<div class="page"><p class="muted">Add yourself and your boss as named members. Estimates are visit durations, not labour hours. Crew jobs appear under each assigned member; do not add these totals together. Older completed visits use saved assignments where attendance was not recorded.</p><section><div class="section-heading"><h2>Members <span class="count">${activeMembers.length}</span></h2></div><div class="team-grid">${activeMembers.map(m=>teamCard(m,'member')).join('')||'<p class="muted">Add your team to assign work by name.</p>'}</div></section><section><div class="section-heading"><h2>Crews <span class="count">${activeCrews.length}</span></h2>${btn('Add Crew','addcrew','plus','secondary')}</div><div class="team-grid">${activeCrews.map(c=>teamCard(c,'crew')).join('')||'<p class="muted">Create a crew when people regularly work together.</p>'}</div></section>${archived.length?`<details><summary>Archived members and crews (${archived.length})</summary><div class="team-grid">${archived.join('')}</div></details>`:''}<section class="panel"><h3>Unassigned work</h3><p class="muted">${state.jobs.filter(j=>j.status!=='completed'&&!j.memberId&&!j.crewId).length} open jobs have no named person or crew.</p>${btn('View schedule','team-schedule','calendar','secondary','data-assignment="unassigned:"')}</section><div class="note">${ic('shield')}<p>Members are assignment records, not login accounts. Access still uses the shared workspace password. Individual logins and worker timers will be added in a later phase.</p></div></div>`;}

function settingsPage(){const s=state.settings;return header('Settings','Manage your workspace')+`<div class="page narrow"><section class="panel"><h2>${ic('team')}Profile</h2><form id="settings-form"><div class="profile large"><div class="avatar">${esc((s.name||'Owner').slice(0,2).toUpperCase())}</div><div><b>${esc(s.name||'Your workspace')}</b><small>Private owner access</small></div></div><div class="form-grid">${input('Display Name','name',s.name,'text','maxlength="200" placeholder="Your name"')}${input('Phone Number','phone',s.phone,'tel','maxlength="100"')}${input('Company Name','company',s.company,'text','maxlength="200" placeholder="Your company"')}${select('Time Zone','timezone',[['Australia/Melbourne','Melbourne / Sydney'],['Australia/Brisbane','Brisbane'],['Australia/Adelaide','Adelaide'],['Australia/Perth','Perth'],['Pacific/Auckland','Auckland'],['Etc/UTC','UTC']],s.timezone)}</div><button class="btn primary" type="submit">Save Changes</button></form></section><section class="panel"><h2>${ic('leaf')}Sample data</h2><p class="muted">Try 4 fictional sites, 6 visits, 2 members, a crew and a finished time entry. Includes reminders, a waiting job and an already-booked follow-up. Sample records appear in your normal schedule and reports. Your existing records are kept.</p>${s.sampleDataAdded?'<p class="muted">Sample data has already been added. You can edit or delete those records normally.</p>':btn('Add sample data','add-sample-data','plus','secondary')}<p class="tiny muted">Fictional sites are labelled [Sample]. Added once, using dates around today.</p></section><section class="panel"><h2>${ic('download')}Backup & restore</h2><p class="muted">Your records are saved online. Download a full backup including job notes and photos, or restore a backup from this version.</p><div class="button-row">${btn('Download Backup','backup','download','primary')}${btn('Restore Backup','restore','clock','secondary')}</div><p class="tiny muted">Restoring replaces this workspace’s records. Export a backup first.</p></section><section class="panel"><h2>${ic('shield')}Workspace access</h2><p class="muted">Only you can open this site through your ChatGPT account. This independent version manages sites, jobs, tasks, crew records and time entries.</p><div class="settings-links">${link('Time Tracking','/time-tracking','clock')}${link('Crews & Members','/crews','team')}</div><details><summary>Migration notes</summary><p class="muted">Existing Lovable accounts, business records and photos have not been imported. Separate crew logins, invitations, GPS geofencing, background push and email notifications are not connected. The site uses ChatGPT private access instead of the original email/password sign-in. Backups use this version’s JSON format.</p></details></section></div>`}
function notFound(){return header('Page not found','This page may have moved')+empty('Let’s get you back to work.','',link('Go to Dashboard','/','dashboard','primary'))}
function openModal(title,body,wide=false,focus=true){lastFocus=document.activeElement;modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" aria-label="Close dialog" data-action="close">${ic('close')}</button></div><div class="modal-body">${body}</div>`;modal.className=wide?'wide':'';if(!modal.open)modal.showModal();if(focus)setTimeout(()=>modal.querySelector('input,select,textarea,button')?.focus(),20)}
function closeModal(){modal.close();lastFocus?.isConnected&&lastFocus.focus()}
const formEnd=(label='Save',extra='')=>`<div class="form-actions">${extra}<button type="button" class="btn secondary" data-action="close">Cancel</button><button type="submit" class="btn primary">${esc(label)}</button></div>`;
function jobForm(id='',date=scheduleDate||today(),siteId=''){if(!state.sites.length){openModal('Add a site first','<p class="muted">Jobs belong to a site. Add your first site to start scheduling.</p>'+link('Add Site','/sites/new','plus','primary'));return}const j=state.jobs.find(x=>x.id===id),selectedSite=j?.siteId||siteId||state.sites[0].id,s=site(selectedSite);openModal(j?'Edit Job':'Schedule a Job',`<form id="job-form" data-id="${id}">${select('Site *','siteId',state.sites.map(s=>[s.id,siteTitle(s)]),selectedSite,'required')}<div class="form-grid">${input('Date *','date',j?.date||date,'date','required')}${input('Start Time','time',j?.time||'','time')}<div id="job-assignment">${assignmentControl(j||defaultAssignment(state,s),'Assigned to',j?.status==='completed')}</div></div>${j?.status==='completed'?'<p class="tiny muted">Completed attendance and assignment history are kept unchanged.</p>':''}${textarea('Job Notes','notes',j?.notes||'','maxlength="5000"')}${formEnd(j?'Save Changes':'Schedule Job')}</form>`);}

function showJob(id){const j=state.jobs.find(x=>x.id===id);if(!j)return;const s=site(j.siteId);openModal(siteTitle(s),`<div class="job-summary">${pill(j.status==='in-progress'?'In progress':j.status==='deferred'?'Waiting to reschedule':j.status,j.status==='deferred'?'amber':'green')}<p>${ic('calendar')}${dateLabel(j.date)} ${esc(j.time)}</p><p>${ic('pin')}${esc(s.address)}</p><p>${ic('team')}${esc(assignee(j))}</p></div>${attendanceSummary(j)}${deferralHistory(j)}${j.status!=='completed'?visitNote(s):''}${btn('Reminder','visit-note','edit','secondary',`data-id="${s.id}"`)}<h3 class="small-heading">Job notes</h3><p class="preserve muted">${esc(j.notes||'No notes added.')}</p>${j.photos.length?`<div class="photos">${j.photos.map(p=>`<a href="${p}" download="job-photo.jpg"><img src="${p}" alt="Photo of completed garden work"></a>`).join('')}</div>`:''}${s.tasks.length?`<h3 class="small-heading">Site checklist</h3>${s.tasks.map(t=>`<p class="muted">${ic(t.done?'check':'leaf')}${esc(t.name)}</p>`).join('')}`:''}<div class="button-row">${j.status==='deferred'?btn('Reschedule','move-job','calendar','secondary',`data-id="${j.id}"`):''}${j.status==='scheduled'?btn('Start Job','startjob','play','primary',`data-id="${id}"`):j.status==='in-progress'?btn('Complete Job','complete','check','primary',`data-id="${id}"`):''}${['scheduled','in-progress'].includes(j.status)?btn('Defer job','defer-job','clock','secondary',`data-id="${id}"`):''}${j.status==='deferred'?btn('Do today','do-today','calendar','primary',`data-id="${id}"`):''}${btn('Edit Job','editjob','edit','secondary',`data-id="${id}"`)}${link('View Site','/sites/'+j.siteId,'pin')}</div><div class="modal-footer">${btn('Delete Job','deletejob','trash','text-danger',`data-id="${id}"`)}</div>`)}
function autoScheduleForm(){if(!state.sites.length)return jobForm();const range=weekRange(scheduleDate||today());showAutoPreview(range.start,range.end);}

let weeklyDraft=null;
function showAutoPreview(start,end,options=state.settings.planner||{}){const plan=buildWeeklyPlan(state,start,end,today(),options);weeklyDraft={...plan,start,end,rows:[...plan.planned.map(r=>({...r,included:true})),...plan.needs.map(r=>({...r,included:false}))]};renderWeeklyDraft();}
function syncWeeklyDraft(){if(weeklyDraft)weeklyDraft.expanded=[...document.querySelectorAll('.draft-day details[open]')].map(el=>el.closest('[data-draft-day]').dataset.draftDay);const form=$('#weekly-plan-form');if(!form||!weeklyDraft)return;const fd=new FormData(form),selected=new Set(fd.getAll('include'));for(const row of weeklyDraft.rows){row.included=selected.has(row.siteId);row.date=fd.get('date_'+row.siteId)||'';row.assignment=fd.get('assignment_'+row.siteId)||'';}}
function draftRow(row){const s=site(row.siteId),options=[['','Needs allocation']];for(let day=weeklyDraft.start;day<=weeklyDraft.end;day=addDays(day,1))if(day>=today())options.push([day,dateLabel(day)]);const assigned=row.assignment===undefined?row:assignmentFields(state,row.assignment,row);return `<div class="draft-row" data-draft-row="${row.siteId}"><div class="draft-title"><label class="check-field"><input type="checkbox" name="include" value="${row.siteId}" ${row.included?'checked':''}><b>${esc(siteTitle(s))}</b></label><button type="button" class="draft-handle" data-draft-id="${row.siteId}" aria-label="Drag visit to a day">↕</button></div><p class="tiny muted">${esc(s.addressParts?.confirmed?s.addressParts.suburb:'Address needs review')} · ${esc(s.estimatedTime||'No estimate')} · ${esc(row.issue||row.reason)}</p><input type="hidden" name="source_${row.siteId}" value="${row.jobId}"><div class="form-grid">${select('Day','date_'+row.siteId,options,row.date)}${assignmentControl(assigned).replace('name="assignment"','name="assignment_'+row.siteId+'"')}</div></div>`;}
function renderWeeklyDraft(refresh=false){const scroll=modal.scrollTop||0;const d=weeklyDraft;if(!d)return;let feedback='';const selected=d.rows.filter(r=>r.included&&r.date),pending=d.rows.filter(r=>!r.included||!r.date),days=[];for(let day=d.start;day<=d.end;day=addDays(day,1))days.push(day);if(selected.length){try{let n=0;saveWeeklyPlan(structuredClone(state),selected,d.start,d.end,today(),d.options,()=> 'draft_check_'+(++n));}catch(e){feedback=e.message;}}openModal('Plan this week · '+dateLabel(d.start)+' – '+dateLabel(d.end),`<details class="planner-options"><summary>Working days & daily limits</summary><form id="planner-options-form"><div class="form-grid">${input('Visits per person / crew','maxJobs',d.options.maxJobs,'number','required min="1" max="30"')}${input('Daily hours including buffer','maxHours',d.options.maxHours,'number','required min="1" max="16" step="0.5"')}${input('Buffer per visit (minutes)','buffer',d.options.buffer,'number','required min="0" max="120"')}</div><div class="weekday-options">${[1,2,3,4,5,6,0].map(n=>`<label><input type="checkbox" name="weekday" value="${n}" ${d.options.weekdays.includes(n)?'checked':''}>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][n]}</label>`).join('')}</div><p class="tiny muted">Rebuilding replaces draft adjustments. Limits count existing visits and crew members’ other assignments. Buffer is an allowance, not measured driving time.</p><button class="btn secondary" type="submit">Rebuild draft</button></form></details><p class="muted">${selected.length} proposed · ${pending.length} need allocation · ${d.fixed.length} existing bookings. Expand a day to adjust its visits, or drag ↕ between days.</p><p class="tiny muted">Groups confirmed addresses by suburb and keeps preferred weekdays. Existing bookings stay fixed. This plan covers everyone, regardless of schedule filters.</p><form id="weekly-plan-form" data-start="${d.start}" data-end="${d.end}"><div class="draft-week">${days.map(day=>{const rows=selected.filter(r=>r.date===day),fixed=d.fixed.filter(j=>j.date===day),all=[...fixed,...rows],suburbs=[...new Set(all.map(j=>site(j.siteId)?.addressParts).filter(p=>p?.confirmed).map(p=>p.suburb))],groups=new Map();for(const j of all){const label=j.assignment!==undefined?assignee({...j,...assignmentFields(state,j.assignment,j)}):assignee(j);const list=groups.get(label)||[];list.push(j);groups.set(label,list);}const warnings=weeklyDayWarnings(state,all.map(j=>j.assignment!==undefined?{...j,...assignmentFields(state,j.assignment,j)}:j),d.options);return `<section class="draft-day ${warnings.length?'draft-overload':''}" data-draft-day="${day}"><details ${d.expanded?.includes(day)?'open':''}><summary><strong>${dateLabel(day)}</strong><span>${workloadLabel(all)} · ${rows.length} proposed</span><small>${esc(suburbs.join(', ')||'No suburb group')}</small></summary>${warnings.map(w=>`<p class="notice amber">${esc(w)}</p>`).join('')}${[...groups].map(([label,jobs])=>`<p class="tiny muted">${esc(label)} · ${workloadLabel(jobs)}</p>`).join('')}${fixed.map(j=>`<p class="draft-fixed">${ic('calendar')} ${esc(siteTitle(site(j.siteId)))}${j.time?' · '+esc(j.time):''} · Existing booking</p>`).join('')}${rows.map(draftRow).join('')||(!fixed.length?'<p class="tiny muted">No visits allocated.</p>':'')}</details></section>`}).join('')}</div><details class="draft-pending" ${pending.length?'open':''}><summary>Needs allocation (${pending.length})</summary><p class="tiny muted">These visits will stay unchanged until you select a day, assignment and checkbox. Unconfirmed addresses can be allocated manually; they are not used for suburb grouping.</p>${pending.map(draftRow).join('')}</details>${d.skipped.length?`<details><summary>${d.skipped.length} sites left unchanged</summary>${d.skipped.map(r=>`<p class="tiny muted">${esc(siteTitle(site(r.siteId)))} — ${esc(r.reason)}</p>`).join('')}</details>`:''}<p id="draft-feedback" role="status" class="tiny muted">${esc(feedback||'Daily limits and dates checked. Ready to save selected visits.')}</p><div class="form-actions">${btn('Cancel','close','close','secondary','type="button"')}<button class="btn primary" type="submit" ${selected.length?'':'disabled'}>Save weekly plan</button></div></form>`,true,!refresh);if(refresh)modal.scrollTop=scroll;}
function moveDraftVisit(id,date){syncWeeklyDraft();const row=weeklyDraft?.rows.find(r=>r.siteId===id);if(!row)return;if(date<today()||date<weeklyDraft.start||date>weeklyDraft.end)return toast('Choose a remaining day in this week.',true);row.date=date;row.included=true;weeklyDraft.expanded=[...(weeklyDraft.expanded||[]),date];renderWeeklyDraft(true);}

function followUpControl(job,s){
 if(s.frequency==='one-off')return '';
 const next=preferredDate(s,nextVisit({...s,lastCompleted:job.date})),existing=existingFollowUp(state.jobs,job,next);
 if(existing?.status==='deferred')return '<div class="notice"><b>This site has a job waiting to reschedule.</b><p>No extra visit will be created. Reschedule the waiting job when ready.</p></div>';
 if(existing)return `<div class="notice"><b>${existing.status==='completed'?'A visit already exists':'Next visit already scheduled'} · ${dateLabel(existing.date)}</b><p>No extra visit will be created. Your existing booking stays unchanged.</p></div>`;
 return `<label class="check-field"><input type="checkbox" name="followup" checked>Schedule next visit</label>${input('Next visit date','nextDate',next,'date',`min="${addDays(job.date,1)}"`)}<p class="tiny muted">Based on this visit’s date, frequency and preferred weekday. Change the date or untick to schedule later.</p>`;
}
function completeForm(id){const j=state.jobs.find(x=>x.id===id);const s=site(j.siteId);openModal('Complete Job',`<form id="complete-form" data-id="${id}"><p class="muted">${esc(siteTitle(s))} · ${dateLabel(j.date)}</p>${textarea('Reminder','nextVisitNote',s.nextVisitNote,'maxlength="2000" placeholder="e.g. Trim back bushes next time"')}<p class="tiny muted">This stays highlighted for future visits until you clear it.</p>${attendanceControl(j)}${textarea('Completion Notes','notes',j.notes,'maxlength="5000" placeholder="Work completed, follow-ups or anything to remember"')}${s.tasks.length?`<div class="tasks">${s.tasks.map(t=>`<label class="check-field"><input type="checkbox" name="task" value="${t.id}" ${t.done?'checked':''}>${esc(t.name)}</label>`).join('')}</div>`:''}<label class="field">Job Photos <small class="muted">Optional · up to 6 photos · resized before saving</small><input type="file" name="photos" accept="image/jpeg,image/png,image/webp" multiple></label>${followUpControl(j,s)}${formEnd('Complete Job')}</form>`)}
function memberForm(id=''){const m=member(id)||{};openModal(id?'Edit Member':'Add Member',`<form id="member-form" data-id="${id}">${input('Name *','name',m.name,'text','required maxlength="200"')}${input('Role / Job Title','role',m.role,'text','maxlength="200"')}${input('Phone','phone',m.phone,'tel','maxlength="100"')}${input('Email','email',m.email,'email','maxlength="200"')}${formEnd('Save Member',id?btn(m.archived?'Restore member':'Archive member',m.archived?'restore-member':'archive-member','team','secondary',`type="button" data-id="${id}"`):'')}</form>`)}
function crewForm(id=''){const c=crew(id)||{};openModal(id?'Edit Crew':'Add Crew',`<form id="crew-form" data-id="${id}">${input('Crew Name *','name',c.name,'text','required maxlength="200"')}<p class="tiny muted">Changes apply to open work. Completed visit history stays unchanged.</p><p class="small-heading">Crew members</p>${state.members.filter(m=>!m.archived||c.memberIds?.includes(m.id)).map(m=>`<label class="check-field"><input type="checkbox" name="member" value="${m.id}" ${c.memberIds?.includes(m.id)?'checked':''}>${esc(m.name)}${m.archived?' (archived — not assigned to new work)':''}</label>`).join('')||'<p class="muted">You can add members later.</p>'}${formEnd('Save Crew',id?btn(c.archived?'Restore crew':'Archive crew',c.archived?'restore-crew':'archive-crew','team','secondary',`type="button" data-id="${id}"`):'')}</form>`)}
function entryForm(id='',clock=false){if(!state.sites.length){jobForm();return}const e=state.entries.find(x=>x.id===id);const local=s=>{const d=new Date(s||Date.now());return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};openModal(clock?'Clock In':id?'Edit Time Entry':'Add Time Entry',`<form id="entry-form" data-id="${id}" data-clock="${clock}">${select('Site *','siteId',state.sites.map(s=>[s.id,siteTitle(s)]),e?.siteId||'','required')}${!clock?`<p class="tiny muted">Time inputs use this device’s local time zone.</p><div class="form-grid">${input('Clock In *','start',local(e?.start),'datetime-local','required')}${input('Clock Out'+(e&&!e.end?' (leave blank while active)':' *'),'end',e&&!e.end?'':local(e?.end),'datetime-local',e&&!e.end?'':'required')}</div>`:''}${textarea('Notes','notes',e?.notes||'','maxlength="2000"')}${formEnd(clock?'Clock In':'Save Entry',id?btn('Delete','deleteentry','trash','text-danger',`type="button" data-id="${id}"`):'')}</form>`)}
function confirmDelete(title,description,action,id){openModal(title,`<p class="muted">${esc(description)}</p><div class="form-actions"><button class="btn secondary" data-action="close">Cancel</button><button class="btn danger" data-action="${action}" data-id="${id}">Delete</button></div>`)}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(headers,rows,name){const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download(name,[headers,...rows].map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
async function resizePhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Use JPEG, PNG or WebP photos.');if(file.size>15*1024*1024)throw new Error('Each photo must be smaller than 15 MB.');const bitmap=await createImageBitmap(file),scale=Math.min(1,1280/Math.max(bitmap.width,bitmap.height));const c=document.createElement('canvas');c.width=Math.round(bitmap.width*scale);c.height=Math.round(bitmap.height*scale);c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();let data=c.toDataURL('image/jpeg',.72);if(data.length>600000)data=c.toDataURL('image/jpeg',.45);if(data.length>600000)throw new Error('This photo is too large after resizing. Choose a smaller image.');return data}
async function submit(form){const fd=new FormData(form),values=Object.fromEntries(fd),id=form.dataset.id;let ok=false;
 if(form.id==='planner-options-form'){const options=plannerOptions({...values,weekdays:fd.getAll('weekday').map(Number)});return showAutoPreview(weeklyDraft.start,weeklyDraft.end,options);}
 if(form.id==='weekly-plan-form'){syncWeeklyDraft();const rows=weeklyDraft.rows.filter(r=>r.included);if(!rows.length)throw new Error('Select at least one visit.');ok=await save(d=>saveWeeklyPlan(d,rows,weeklyDraft.start,weeklyDraft.end,today(),weeklyDraft.options,uid),'Weekly plan saved');if(ok){weeklyDraft=null;closeModal();}return;}
 if(form.id==='auto-plan-form'){const rows=fd.getAll('include').map(siteId=>({siteId,date:fd.get('date_'+siteId),jobId:fd.get('source_'+siteId)||''}));if(!rows.length)throw new Error('Select at least one visit.');ok=await save(d=>applyAutoPlan(d,rows,form.dataset.start,form.dataset.end,today(),uid),'Visits scheduled');if(ok)closeModal();return;}
 if(form.id==='defer-form'){ok=await save(d=>deferJob(d,id,values.reason),'Job moved to waiting list');if(ok)closeModal();}
 if(form.id==='visit-note-form'){ok=await save(d=>{d.sites.find(x=>x.id===id).nextVisitNote=values.nextVisitNote},'Reminder saved');if(ok)closeModal();}
 if(form.id==='move-job-form'){ok=await saveScheduleMove(id,values.date,values.beforeId);if(ok)closeModal();}
 if(form.id==='site-form'){const {assignment,addressUnit,addressStreet,addressSuburb,addressState,addressPostcode,addressConfirmed,...rest}=values;const data={...rest,...addressFromForm(values,fd,site(id)),...assignmentFields(state,assignment,site(id)),rideOn:fd.has('rideOn')};ok=await save(d=>{if(id){Object.assign(d.sites.find(s=>s.id===id),data)}else d.sites.push({...data,id:uid(),tasks:[],lastCompleted:''})},id?'Site updated':'Site created');if(ok)navigate(id?'/sites/'+id:'/sites')}
 if(form.id==='address-form'){const data=addressFromForm(values,fd,site(id));ok=await save(d=>Object.assign(d.sites.find(s=>s.id===id),data),'Address saved');if(ok)reviewAddresses();return;}
 if(form.id==='settings-form')await save(d=>Object.assign(d.settings,values),'Profile saved');
 if(form.id==='job-form'){const {assignment,...details}=values;ok=await save(d=>{if(id){const j=d.jobs.find(j=>j.id===id);if((j.date!==details.date||j.status==='deferred')&&j.status!=='completed')moveJob(d.jobs,id,details.date);if(j.status!=='completed')Object.assign(j,assignmentFields(d,assignment,j));Object.assign(j,details);}else d.jobs.push({...details,...assignmentFields(d,assignment),id:uid(),status:'scheduled',photos:[]})},'Job saved');if(ok)closeModal()}
 if(form.id==='reassign-form'){ok=await save(d=>reassignJob(d,id,values.assignment),'Assignment updated');if(ok)closeModal();}
 if(form.id==='member-form'){ok=await save(d=>{if(id)Object.assign(d.members.find(m=>m.id===id),values);else d.members.push({...values,id:uid()})},'Member saved');if(ok)closeModal()}
 if(form.id==='crew-form'){const data={name:values.name,memberIds:fd.getAll('member')};ok=await save(d=>{if(id)Object.assign(d.crews.find(c=>c.id===id),data);else d.crews.push({...data,id:uid()})},'Crew saved');if(ok)closeModal()}
 if(form.id==='task-form'){ok=await save(d=>d.sites.find(s=>s.id===id).tasks.push({id:uid(),name:values.name,done:false}),'Task added');if(ok)closeModal()}
 if(form.id==='entry-form'){const clock=form.dataset.clock==='true',start=clock?new Date().toISOString():new Date(values.start).toISOString(),end=clock||!values.end?null:new Date(values.end).toISOString();if(end&&end<start){toast('Clock out must be after clock in.',true);return}if(!end&&state.entries.some(e=>!e.end&&e.id!==id)){toast('Clock out of the active entry first.',true);return}ok=await save(d=>{const data={siteId:values.siteId,start,end,notes:values.notes};if(id)Object.assign(d.entries.find(e=>e.id===id),data);else d.entries.push({...data,id:uid()})},clock?'Clocked in':'Time entry saved');if(ok)closeModal()}
 if(form.id==='complete-form'){const photos=fd.getAll('photos').filter(f=>f.size);let j=state.jobs.find(j=>j.id===id);if(!j||j.status==='completed'){toast('This job has already been completed.');closeModal();return;}if(photos.length+j.photos.length>6){toast('A job can have up to 6 photos.',true);return}const images=await Promise.all(photos.map(resizePhoto));ok=await save(d=>{const job=d.jobs.find(j=>j.id===id),s=d.sites.find(s=>s.id===job.siteId);job.teamSnapshot=snapshotTeam(d,job,fd.getAll('attendee'));job.status='completed';job.completedAt=new Date().toISOString();job.notes=values.notes;job.photos.push(...images);s.lastCompleted=s.lastCompleted&&s.lastCompleted>job.date?s.lastCompleted:job.date;s.nextVisitNote=values.nextVisitNote;s.tasks.forEach(t=>t.done=fd.getAll('task').includes(t.id));for(const e of d.entries)if(e.siteId===s.id&&!e.end)e.end=new Date().toISOString();if(fd.has('followup')&&s.frequency!=='one-off'){const next=values.nextDate||preferredDate(s,nextVisit({...s,lastCompleted:job.date}));if(!validDate(next)||next<=job.date)throw new Error('Choose a next visit date after this visit.');ensureFollowUp(d.jobs,{...job,...defaultAssignment(d,job)},next,uid);}},'Job completed');if(ok)closeModal()}
 if(form.id==='restore-form'){const file=fd.get('backup');if(!file?.size)throw new Error('Choose a backup file.');if(file.size>4*1024*1024)throw new Error('Backup exceeds the Netlify 4 MiB limit.');const backup=JSON.parse(await file.text());if(backup.version!==1||!Array.isArray(backup.sites))throw new Error('Choose a backup from this Gardener Pro version.');if(!fd.has('confirm'))throw new Error('Confirm replacement of current records.');ok=await save(d=>{for(const key of Object.keys(d))delete d[key];Object.assign(d,backup)},'Backup restored');if(ok)closeModal()}
}
async function action(a,el){const id=el.dataset.id;if(a==='add-sample-data'){if(state.settings.sampleDataAdded){toast('Sample data has already been added.');return;}const ok=await save(d=>addSampleData(d,today()),'Sample data added');if(ok){scheduleDate=today();scheduleView='day';scheduleSearch='';scheduleCrew='';navigate('/schedule');}return;}if(a==='logout'){const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});if(!r.ok)throw new Error('Sign out failed. Please retry.');showLogin();return;}
 if(a==='close')return closeModal();
 if(a==='more')return openModal('Workspace',`<div class="mobile-menu">${navs.map(([n,p,i])=>link(n,p,i)).join('')}</div>`);
 if(a==='review-addresses')return reviewAddresses();
 if(a==='review-address')return reviewAddress(id);
 if(a==='edit-site')return navigate('/sites/'+id+'/edit');
 if(a==='schedule-site')return jobForm('',today(),id);
 if(a==='team-schedule'){scheduleDate=today();scheduleView='day';scheduleSearch='';scheduleCrew=el.dataset.assignment;return navigate('/schedule');}
 if(a==='reassign'){const j=state.jobs.find(j=>j.id===id);if(!j||j.status==='completed')return;return openModal('Reassign job',`<form id="reassign-form" data-id="${id}"><p class="muted">${esc(siteTitle(site(j.siteId)))}</p>${assignmentControl(j)}<p class="tiny muted">Changes this visit only. Site defaults stay unchanged.</p>${formEnd('Save assignment')}</form>`);}
 if(['archive-member','archive-crew'].includes(a)){const type=a.slice(8);return openModal('Archive '+type,`<p class="muted">Keep history and existing assignments. Hide this ${type} from new assignments. Review any open jobs still assigned to them.</p><div class="form-actions">${btn('Cancel','close','close','secondary')}${btn('Archive','confirm-'+a,'team','primary',`data-id="${id}"`)}</div>`);}
 if(['confirm-archive-member','confirm-archive-crew','restore-member','restore-crew'].includes(a)){const type=a.endsWith('member')?'member':'crew';const ok=await save(d=>archiveTeamRecord(d,type,id,a.startsWith('confirm-')),'Team updated');if(ok)closeModal();return;}
 if(a==='job-actions')return jobActions(id);
 if(a==='job')return showJob(id);
 if(a==='addjob')return jobForm();
 if(a==='addjob-date')return jobForm('',el.dataset.date);
 if(a==='editjob')return jobForm(id);
 if(a==='defer-job')return openModal('Defer job',`<form id="defer-form" data-id="${id}">${textarea('Why could this job not be completed?','reason','','required maxlength="2000" placeholder="e.g. Heavy rain — return when dry"')}<p class="muted">Moves this job to Waiting to reschedule. Any running timer for this site will stop; recorded time is kept.</p>${formEnd('Move to waiting list')}</form>`);
 if(a==='do-today'){const ok=await saveScheduleMove(id,today());if(ok)closeModal();return;}
 if(a==='visit-note'){const s=site(id);return openModal('Reminder',`<form id="visit-note-form" data-id="${id}">${textarea('Reminder','nextVisitNote',s.nextVisitNote,'maxlength="2000" placeholder="Trim back bushes next time"')}<p class="muted">Shown on future visits until you clear it. Leave blank to remove.</p>${formEnd('Save reminder')}</form>`);}
 if(a==='move-job')return moveJobForm(id);
 if(a==='undo-schedule'){if(!scheduleUndo||scheduleUndo.revision!==revision)return toast('Undo is no longer available.',true);const previous=scheduleUndo.snapshot;const ok=await save(d=>restoreSchedule(d.jobs,previous),'Schedule move undone');if(ok)render();return;}
 if(a==='view-waiting'){scheduleView='waiting';return render();}
 if(a==='view-today'){scheduleDate=today();scheduleView='day';return render();}
 if(a==='view-week'||a==='view-day'){scheduleView=a==='view-week'?'week':'day';return render()}
 if(a==='choose-day'){scheduleDate=el.dataset.date;scheduleView='day';return render()}
 if(a==='prev-date'||a==='next-date'){scheduleDate=shiftDate(scheduleDate,(a==='prev-date'?-1:1)*(scheduleView==='week'?7:1));return render()}
 if(a==='today'){scheduleDate=today();return render()}
 if(a==='clear-history'){historyDate='';return render()}
 if(a==='startjob'){const job=state.jobs.find(j=>j.id===id),active=activeEntry();if(active&&active.siteId!==job.siteId){toast('Clock out of the current site before starting another job.',true);return}const ok=await save(d=>{const j=d.jobs.find(j=>j.id===id);j.status='in-progress';j.startedAt=new Date().toISOString();if(!d.entries.some(e=>!e.end))d.entries.push({id:uid(),siteId:j.siteId,start:j.startedAt,end:null,notes:''})},'Job started · timer running');if(ok&&modal.open)showJob(id);return}
 if(a==='complete')return completeForm(id);
 if(a==='clockin')return entryForm('',true);
 if(a==='clockout'){await save(d=>{let e=d.entries.find(e=>!e.end);if(e)e.end=new Date().toISOString()},'Clocked out');return}
 if(a==='addentry'||a==='editentry')return entryForm(id||'');
 if(a==='addmember'||a==='editmember')return memberForm(id||'');
 if(a==='addcrew'||a==='editcrew')return crewForm(id||'');
 if(a==='addtask')return openModal('Add Task',`<form id="task-form" data-id="${id}">${input('Task Name *','name','','text','required maxlength="300" placeholder="e.g. Mow lawn"')}${formEnd('Add Task')}</form>`);
 if(a==='delete-task'){await save(d=>{const s=d.sites.find(s=>s.id===el.dataset.site);s.tasks=s.tasks.filter(t=>t.id!==id)},'Task deleted');return}
 if(a==='delete-site')return confirmDelete('Delete Site','This removes the site, its tasks, jobs, photos and time entries. Export a backup first if you need them.','confirm-delete-site',id);
 if(a==='confirm-delete-site'){const ok=await save(d=>{d.sites=d.sites.filter(s=>s.id!==id);d.jobs=d.jobs.filter(j=>j.siteId!==id);d.entries=d.entries.filter(e=>e.siteId!==id)},'Site deleted');if(ok){closeModal();navigate('/sites')}return}
 if(['deletejob','deleteentry'].includes(a))return confirmDelete('Delete '+a.replace('delete',''),'This record will be permanently removed.','confirm-'+a,id);
 if(['confirm-deletejob','confirm-deleteentry'].includes(a)){const key=a==='confirm-deletejob'?'jobs':'entries';const ok=await save(d=>{d[key]=d[key].filter(x=>x.id!==id)},'Record deleted');if(ok)closeModal();return;}
 if(a==='autoschedule')return autoScheduleForm();
 if(a==='backup')return download('gardener-pro-backup-'+today()+'.json',JSON.stringify(state,null,2));
 if(a==='restore')return openModal('Restore Backup',`<form id="restore-form"><p class="muted">This replaces all current records. Download a backup before continuing.</p>${btn('Download Current Backup','backup','download','secondary','type="button"')}<label class="field">Backup File<input type="file" name="backup" accept=".json,application/json" required></label><label class="check-field"><input type="checkbox" name="confirm" required>I understand this replaces all current records.</label>${formEnd('Restore Backup')}</form>`);
 if(a==='export-sites')return csv(['Name','Address','Unit','Street','Suburb','State','Postcode','Address confirmed','Frequency','Estimated Time','Preferred Day','Ride-on Required','Parking','Notes'],state.sites.map(s=>[s.name,s.address,s.addressParts?.unit||'',s.addressParts?.street||'',s.addressParts?.suburb||'',s.addressParts?.state||'',s.addressParts?.postcode||'',s.addressParts?.confirmed?'Yes':'No',s.frequency,s.estimatedTime,s.preferredDay,s.rideOn?'Yes':'No',s.parking,s.notes]),'gardener-pro-sites.csv');
 if(a==='export-history')return csv(['Site','Date','Assigned To','Attendees','Attendance Source','Completed At','Notes'],state.jobs.filter(j=>j.status==='completed'&&(!historyDate||j.date===historyDate)).map(j=>[siteTitle(site(j.siteId)),j.date,assignee(j),j.teamSnapshot?.source==='confirmed'?j.teamSnapshot.members.map(m=>m.name).join('; '):'',j.teamSnapshot?.source||'not-recorded',j.completedAt,j.notes]),'gardener-pro-history.csv');
 if(a==='export-time')return csv(['Site','Clock In','Clock Out','Duration','Notes'],state.entries.map(e=>[siteTitle(site(e.siteId)),e.start,e.end||'',duration(e.start,e.end),e.notes]),'gardener-pro-time.csv');
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el.dataset.action,el).catch(err=>toast(err.message,true));return}const a=e.target.closest('a[href]');if(a&&a.getAttribute('href').startsWith('/')&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();if(modal.open)closeModal();navigate(a.getAttribute('href'))}});
document.addEventListener('submit',async e=>{if(!e.target.id.endsWith('-form'))return;e.preventDefault();const button=e.target.querySelector('button[type="submit"]');if(button)button.disabled=true;try{await submit(e.target)}catch(err){toast(err.message||'Unable to save. Please check the form.',true)}finally{if(button?.isConnected)button.disabled=false}});
document.addEventListener('change',async e=>{if(e.target.closest('#weekly-plan-form')){syncWeeklyDraft();if(e.target.name.startsWith('date_'))weeklyDraft.expanded=[...(weeklyDraft.expanded||[]),e.target.value];return renderWeeklyDraft(true);}if(e.target.name==='siteId'&&e.target.closest('#job-form')){const form=e.target.closest('#job-form'),j=state.jobs.find(j=>j.id===form.dataset.id);if(j?.status!=='completed')$('#job-assignment').innerHTML=assignmentControl(defaultAssignment(state,site(e.target.value)));}if(e.target.id==='site-filter'){filter=e.target.value;history.replaceState({},'','/sites');renderListOnly()}if(e.target.id==='schedule-date'){scheduleDate=e.target.value||today();render()}if(e.target.id==='history-date'){historyDate=e.target.value;render()}if(e.target.dataset.task){const checked=e.target.checked,tid=e.target.dataset.task,sid=e.target.dataset.site;const ok=await save(d=>d.sites.find(s=>s.id===sid).tasks.find(t=>t.id===tid).done=checked,'Task updated');if(!ok)e.target.checked=!checked}});
window.addEventListener('popstate',()=>{search='';filter='all';render()});
modal.addEventListener('click',e=>{if(e.target===modal&&e.clientX&&(e.clientX<modal.getBoundingClientRect().left||e.clientX>modal.getBoundingClientRect().right||e.clientY<modal.getBoundingClientRect().top||e.clientY>modal.getBoundingClientRect().bottom))closeModal()});
function updateTimers(){if(!state)return;$$('[data-timer]').forEach(el=>{const e=state.entries.find(e=>e.id===el.dataset.timer);if(e)el.textContent=duration(e.start,e.end)})}setInterval(updateTimers,15000);
load().then(render).catch(e=>{if(!state&&document.querySelector('#login'))return;showLogin(e.message);});

function showLogin(message=''){
 state=null;revision=0;if(modal.open)modal.close();modal.innerHTML='';document.title='Sign in · Gardener Pro';
 $('#app').innerHTML=`<main id="main" class="login-page"><section class="login-card"><img src="/icon.svg" alt="" width="64" height="64"><p class="login-eyebrow">GARDENER PRO</p><h1>Your workday, organised.</h1><p>Manage your sites, schedules and team in one place.</p><form id="login"><label class="field">Workspace password<input name="password" type="password" autocomplete="current-password" required maxlength="1024" autofocus></label><button class="btn primary" type="submit">Sign in</button><p id="login-message" role="status">${esc(message)}</p></form><small>Business records are only available after you sign in.</small></section></main>`;
 $('#login').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('#login-message').textContent='Signing in…';try{const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'login',password:new FormData(e.target).get('password')})});if(r.status===429)throw new Error('Too many attempts. Wait a minute and try again.');const body=await r.json();if(!r.ok)throw new Error(body.error||'Unable to sign in.');e.target.reset();await load();render();}catch(err){const msg=$('#login-message');if(msg)msg.textContent=err.message;}finally{if(b.isConnected)b.disabled=false;}});
}
window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});

function moveJobForm(id){const j=state.jobs.find(x=>x.id===id);if(!j||j.status==='completed')return;
 openModal('Move or reorder job',`<form id="move-job-form" data-id="${id}">${input('Date','date',j.status==='deferred'?today():j.date,'date','required')}<div id="move-position"></div><p class="tiny muted">${j.status==='deferred'?'Choose a new day. The old start time is cleared; assignment and notes are kept.':'The job keeps its start time and assignment.'}</p>${formEnd('Move job')}</form>`);
 const date=modal.querySelector('[name="date"]');const positions=()=>{$('#move-position').innerHTML=select('Place before','beforeId',[['','End of day'],...state.jobs.filter(x=>x.status!=='deferred'&&x.date===date.value&&x.id!==id).sort(compareJobs).map(x=>[x.id,(siteTitle(site(x.siteId)))+' · '+(x.time||'Flexible')])]);};date.addEventListener('change',positions);positions();
}
let scheduleDrag=null,suppressDragClick=false;
function clearScheduleDrag(){document.querySelectorAll('.drop-target,.drop-before,.dragging-job').forEach(el=>el.classList.remove('drop-target','drop-before','dragging-job'));scheduleDrag=null;}
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('.drag-handle');if(!handle||busy||e.button!==0)return;scheduleDrag={id:handle.dataset.id,x:e.clientX,y:e.clientY,pointer:e.pointerId,handle,active:false,target:null};handle.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{const d=scheduleDrag;if(!d||d.pointer!==e.pointerId)return;if(!d.active&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<7)return;d.active=true;d.handle.closest('.schedule-item').classList.add('dragging-job');document.querySelectorAll('.drop-target,.drop-before').forEach(el=>el.classList.remove('drop-target','drop-before'));const under=document.elementFromPoint(e.clientX,e.clientY),column=under?.closest('[data-drop-date]');d.target=null;if(!column)return;column.classList.add('drop-target');const item=under.closest('.schedule-item');let before='';if(item?.dataset.jobId===d.id){d.target={date:column.dataset.dropDate,before:d.id};return;}if(item){const items=[...column.querySelectorAll('.schedule-item')].filter(x=>x.dataset.jobId!==d.id);const rect=item.getBoundingClientRect();const candidate=e.clientY<rect.top+rect.height/2?item:items[items.indexOf(item)+1];if(candidate&&candidate.dataset.jobId!==d.id){before=candidate.dataset.jobId;candidate.classList.add('drop-before');}}d.target={date:column.dataset.dropDate,before};const grid=column.closest('.week-grid'),rect=grid.getBoundingClientRect();if(e.clientX>rect.right-35)grid.scrollLeft+=18;if(e.clientX<rect.left+35)grid.scrollLeft-=18;if(e.clientY>innerHeight-70)window.scrollBy(0,18);if(e.clientY<90)window.scrollBy(0,-18);});
document.addEventListener('pointerup',async e=>{const d=scheduleDrag;if(!d||d.pointer!==e.pointerId)return;const target=d.target,active=d.active;clearScheduleDrag();if(active){suppressDragClick=true;setTimeout(()=>suppressDragClick=false,0);if(target)await saveScheduleMove(d.id,target.date,target.before);}});
document.addEventListener('pointercancel',clearScheduleDrag);
document.addEventListener('keydown',e=>{if(e.key==='Escape')clearScheduleDrag();});
document.addEventListener('click',e=>{if(suppressDragClick){e.preventDefault();e.stopImmediatePropagation();}},true);

function deferralNote(j){const last=j.deferrals?.at(-1);return last?`<span class="next-visit-note"><strong>${j.status==='deferred'?'Deferred':'Previously deferred'} · ${dateLabel(last.date)}</strong><span>${esc(last.reason)}</span></span>`:'';}
function deferralHistory(j){return j.deferrals?.length?`<section><h3>Deferral history</h3>${j.deferrals.map(x=>`<p class="preserve"><b>${dateLabel(x.date)}</b> · ${esc(x.reason)}</p>`).join('')}</section>`:'';}
function deferredQueue(){const waiting=state.jobs.filter(j=>j.status==='deferred'&&scheduleMatches(j)).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id));return `<section class="deferred-queue"><div class="section-heading"><h2>Waiting to reschedule <span class="count">${waiting.length}</span></h2></div><p class="muted">Unfinished jobs from any week. Choose a day when you have time.</p>${waiting.length?`<div class="waiting-grid">${waiting.map(scheduleCard).join('')}</div>`:'<p class="muted">No waiting jobs match this view.</p>'}</section>`;}
function setSaveStatus(message){saveMessage=message;const el=$('#save-state');if(el)el.textContent=message;}
async function saveScheduleMove(id,date,before=''){if(busy)return false;const snapshot=scheduleSnapshot(state.jobs);const ok=await save(d=>moveJob(d.jobs,id,date,before),'Schedule updated');if(ok){scheduleUndo={snapshot,revision};render();}return ok;}
document.addEventListener('input',e=>{if(e.target.id==='schedule-search'){const value=e.target.value,position=e.target.selectionStart;scheduleSearch=value;render();const input=$('#schedule-search');input.focus();try{input.setSelectionRange(position,position);}catch{}}});
document.addEventListener('change',e=>{if(e.target.id==='schedule-crew'){scheduleCrew=e.target.value;render();}});

let draftPointer=null;
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('.draft-handle');if(!handle||e.button!==0)return;draftPointer={id:handle.dataset.draftId,x:e.clientX,y:e.clientY,pointer:e.pointerId,handle,active:false,date:null};handle.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{const p=draftPointer;if(!p||p.pointer!==e.pointerId)return;if(!p.active&&Math.hypot(e.clientX-p.x,e.clientY-p.y)<7)return;p.active=true;const day=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-draft-day]');document.querySelectorAll('.draft-drop').forEach(el=>el.classList.remove('draft-drop'));p.date=day?.dataset.draftDay||null;if(day)day.classList.add('draft-drop');const body=modal.querySelector('.modal-body');if(body){const r=body.getBoundingClientRect();if(e.clientY>r.bottom-50)body.scrollTop+=18;if(e.clientY<r.top+50)body.scrollTop-=18;}});
document.addEventListener('pointerup',e=>{const p=draftPointer;if(!p||p.pointer!==e.pointerId)return;draftPointer=null;document.querySelectorAll('.draft-drop').forEach(el=>el.classList.remove('draft-drop'));if(p.active&&p.date)moveDraftVisit(p.id,p.date);});
document.addEventListener('pointercancel',()=>{draftPointer=null;document.querySelectorAll('.draft-drop').forEach(el=>el.classList.remove('draft-drop'));});
